import { after } from "next/server";
import { revalidateTag } from "next/cache";
import { getCachedProducts, PRODUCTS_TAG } from "@/lib/products";
import { syncFromUpstream } from "@/lib/db.js";

async function syncCatalogAction() {
  "use server";

  after(async () => {
    await syncFromUpstream();
    revalidateTag(PRODUCTS_TAG);
  });
}

export default async function AdminCatalogPage() {
  const products = await getCachedProducts();

  return (
    <div className="min-h-screen bg-zinc-50 p-8">
      <header className="mb-8 flex items-center justify-between border-b border-zinc-200 pb-6">
        <h1 className="text-2xl font-semibold text-zinc-900">
          Product Catalog
        </h1>
        <form action={syncCatalogAction}>
          <button
            type="submit"
            className="rounded-lg bg-zinc-900 px-4 py-2 text-sm font-medium text-white transition hover:bg-zinc-800"
          >
            Sync latest catalog
          </button>
        </form>
      </header>

      <p className="mb-6 text-sm text-zinc-500">
        Catalog data is cached for fast browsing. Use &quot;Sync latest
        catalog&quot; when upstream ERP/PIM data changes. The sync runs in the
        background—you can keep working while it completes.
      </p>

      <div className="overflow-hidden rounded-lg border border-zinc-200 bg-white shadow-sm">
        <table className="min-w-full divide-y divide-zinc-200">
          <thead>
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider text-zinc-500">
                ID
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider text-zinc-500">
                Name
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider text-zinc-500">
                Price
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-200">
            {products.map((product) => (
              <tr key={product.id} className="hover:bg-zinc-50">
                <td className="whitespace-nowrap px-6 py-4 text-sm text-zinc-900">
                  {product.id}
                </td>
                <td className="whitespace-nowrap px-6 py-4 text-sm font-medium text-zinc-900">
                  {product.name}
                </td>
                <td className="whitespace-nowrap px-6 py-4 text-sm text-zinc-600">
                  ${product.price}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

